class Program {
    static class Labeler {
        String label(Object value) { return "object"; }
        String label(String value) { return "string"; }
    }
    static class Detailed extends Labeler {
        @Override String label(Object value) { return "detailed"; }
    }
    public static void main(String[] args) {
        Labeler receiver = new Detailed();
        Object value = "hello";
        System.out.println(receiver.label(value));
        System.out.println(receiver.label("hello"));
    }
}
